class Cart:
    def __init__(self):
        self.items = {}

    def add(self, name, price, quantity=1):
        self.items[name] = (price, quantity)

    def subtotal(self):
        return sum(price * qty for price, qty in self.items.values())

    def total(self, discount_percent=0):
        return self.subtotal() * (1 + discount_percent / 100)

