def initials(name):
    return "".join(word[0].upper() for word in name.split(" "))


def slug(text):
    return "-".join(text.lower().split())

files.test_text_utils.py:
from text_utils import initials, slug


def test_initials():
    assert initials("Ada Lovelace") == "AL"


def test_single():
    assert initials("Ada") == "A"


def test_whitespace():
    assert initials("  Ada   Lovelace  ") == "AL"


def test_slug():
    assert slug("Hello World") == "hello-world"


def test_slug_spaces():
    assert slug("  Hello   World ") == "hello-world"

